result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "smoothing.py", "content": """"A* pathfinding on a 4-connected grid + line-of-sight string-pull smoothing."""

from heapq import heappush, heappop


def parse_grid(text):
    """Parse map text into (grid, start, goal). 'S' start, 'G' goal,
    '#' wall, '-' open."""
    grid = []
    start = goal = None
    for r, line in enumerate(text.strip("\n").splitlines()):
        row = list(line)
        for c, ch in enumerate(row):
            if ch == "S":
                start = (r, c)
            elif ch == "G":
                goal = (r, c)
        grid.append(row)
    if start is None or goal is None:
        raise ValueError("map needs both S and G")
    return grid, start, goal


def neighbors(pos, grid):
    r, c = pos
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] != "#":
            yield (nr, nc)


def astar(grid, start, goal):
    """4-connected A* with Manhattan heuristic. Returns list of cells
    [start, ..., goal] or None if unreachable."""
    def h(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    open_set = [(h(start, goal), 0.0, start)]
    came_from = {}
    g_score = {start: 0.0}
    closed = set()

    while open_set:
        _, g, cur = heappop(open_set)
        if cur == goal:
            path = [cur]
            while cur in came_from:
                cur = came_from[cur]
                path.append(cur)
            return path[::-1]
        if cur in closed:
            continue
        closed.add(cur)
        for nb in neighbors(cur, grid):
            ng = g + 1.0
            if ng < g_score.get(nb, float("inf")):
                g_score[nb] = ng
                came_from[nb] = cur
                heappush(open_set, (ng + h(nb, goal), ng, nb))
    return None


def bresenham(a, b):
    """All grid cells on the Bresenham line from a to b (inclusive)."""
    (x0, y0), (x1, y1) = a, b
    dx, dy = abs(x1 - x0), abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx - dy
    cells = []
    x, y = x0, y0
    while True:
        cells.append((x, y))
        if (x, y) == (x1, y1):
            break
        e2 = 2 * err
        if e2 > -dy:
            err -= dy
            x += sx
        if e2 < dx:
            err += dx
            y += sy
    return cells


def line_of_sight(a, b, grid):
    """True if the Bresenham line a->b crosses only open cells."""
    return all(
        0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] != "#"
        for r, c in bresenham(a, b)
    )


def smooth(path, grid):
    """Greedy string pulling: keep a waypoint, then advance as far ahead
    as line-of-sight allows."""
    smoothed = [path[0]]
    i = 0
    while i < len(path) - 1:
        j = len(path) - 1
        while j > i + 1 and not line_of_sight(path[i], path[j], grid):
            j -= 1
        smoothed.append(path[j])
        i = j
    return smoothed


def path_length(path):
    return sum(
        ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5
        for a, b in zip(path, path[1:])
    )


MAP = """
S---------
-########-
----------
-########-
---------G
"""


def main():
    grid, start, goal = parse_grid(MAP)
    raw = astar(grid, start, goal)
    smoothed = smooth(raw, grid)
    print(f"raw waypoints:      {len(raw)}")
    print(f"smoothed waypoints: {len(smoothed)}")
    print(f"raw path:      {raw}")
    print(f"smoothed path: {smoothed}")
    print(f"length raw={path_length(raw):.2f} smoothed={path_length(smoothed):.2f}")
